function newId(){if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}
import {createClient} from './vendor/supabase.js';
const config=await fetch('/assets/public-config.json').then(r=>r.json());
const sb=createClient(config.supabaseUrl,config.publishableKey,{auth:{flowType:'pkce'}});
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n/100);
const when=v=>v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'})+' IST':'To be announced';
function status(msg,error=false){const el=$('#app-status');if(el){el.textContent=msg;el.className=error?'app-status error':'app-status';}}
function result(r){if(r.error)throw r.error;return r.data;}
async function api(action,body={}){const {data:{session}}=await sb.auth.getSession();const r=await fetch(config.supabaseUrl+'/functions/v1/elan-api',{method:'POST',headers:{'Content-Type':'application/json',apikey:config.publishableKey,...(session?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,...body})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed.');return d;}
function bind(form,fn){form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const buttons=form.querySelectorAll('button[type=submit]');buttons.forEach(b=>b.disabled=true);status('Saving…');try{await fn(Object.fromEntries(new FormData(form)),form);}catch(e){status(e.message,true);}finally{buttons.forEach(b=>b.disabled=false);}});}
const field=(name,label,type='text',value='',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}" maxlength="20000">${esc(value)}</textarea></label>`;
const select=(name,label,options,value='')=>`<label>${esc(label)}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const check=(name,label,yes=false)=>`<label class="checkbox"><input type="checkbox" name="${name}" ${yes?'checked':''}>${esc(label)}</label>`;
const submit=label=>`<button type="submit">${label}</button>`;
function downloadCSV(rows){if(!rows.length)return;const cols=Object.keys(rows[0]).filter(k=>!Array.isArray(rows[0][k])&&typeof rows[0][k]!=='object');const q=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[cols.map(q).join(','),...rows.map(r=>cols.map(k=>q(r[k])).join(','))].join('\r\n')],{type:'text/csv'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='elan-export.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
// Saved enquiries replace email-draft-only forms.
for(const form of document.querySelectorAll('form[data-mode="stored-enquiry"]')){
 form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;let note=form.querySelector('.enquiry-status');if(!note){note=document.createElement('p');note.className='enquiry-status';note.setAttribute('role','status');form.append(note);}note.textContent='Sending your enquiry…';
 try{const details={};for(const input of form.querySelectorAll('input,select,textarea')){if(input.name==='elan_hp'||input.name==='contact_consent')continue;details[input.id||input.name]=input.type==='checkbox'?input.checked:input.value;}
 const inputs=[...form.querySelectorAll('input')];const full_name=inputs.find(x=>x.dataset.validate==='name')?.value||details.coordinator;const email=inputs.find(x=>x.type==='email')?.value;
 const r=await api('enquiry',{kind:form.dataset.form,full_name,email,details,consent:form.querySelector('[name=contact_consent]').checked,honeypot:form.querySelector('[name=elan_hp]')?.value||'',captchaToken:form.querySelector('[name="cf-turnstile-response"]')?.value||''});note.textContent='Your enquiry has been saved. Reference: '+r.id+'. The team can now review it.';form.reset();}catch(e){note.textContent=e.message;}finally{button.disabled=false;}
 });
}
if(config.turnstileSiteKey&&document.querySelector('form[data-mode="stored-enquiry"]')){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js';script.async=true;for(const f of document.querySelectorAll('form[data-mode="stored-enquiry"]')){const div=document.createElement('div');div.className='cf-turnstile';div.dataset.sitekey=config.turnstileSiteKey;f.append(div);}document.head.append(script);}
function adminLogin(){
 status('');
 $('#app-content').innerHTML=`<div class="admin-welcome"><section class="app-card"><span class="app-badge">TEAM ACCESS</span><h2>Sign in to manage Élan.</h2><p>Use the verified email assigned to your organiser account.</p><form class="app-form" id="admin-login-form">${field('email','Email','email','','required autocomplete="email"')}${field('password','Password','password','','required autocomplete="current-password"')}${submit('Open workspace')}</form><p><a href="/portal/login.html?next=admin">Forgot your password?</a></p></section><aside class="admin-intro"><p class="section-label">YOUR WORKSPACE</p><h2>Keep the event<br>moving.</h2><ul><li>Follow up on school and volunteer enquiries</li><li>Manage registrations and check in delegates</li><li>Update guests, photos and the programme</li><li>Publish announcements for participants</li></ul><p>Access is restricted to authorised organisers.</p></aside></div>`;
 bind($('#admin-login-form'),async d=>{result(await sb.auth.signInWithPassword(d));location.href='/admin.html';});
}
function login(){status('');$('#app-content').innerHTML=`<div class="app-grid"><section class="app-card"><h2>Welcome back.</h2><form class="app-form" id="login-form">${field('email','Email','email','','required autocomplete="email"')}${field('password','Password','password','','required autocomplete="current-password"')}${submit('Sign in')}</form></section><section class="app-card"><h2>Start your account.</h2><form class="app-form" id="signup-form">${field('email','Email','email','','required autocomplete="email"')}${field('password','Password · at least 12 characters','password','','required minlength="12" autocomplete="new-password"')}<p class="form-note">An account does not reserve a place. You’ll review participation terms when registration opens.</p>${submit('Create account')}</form></section></div><section class="app-card"><h2>Need a new link?</h2><form class="app-form" id="recovery-form">${field('email','Email','email','','required')}${select('kind','Email to request',[['reset','Reset password'],['confirm','Resend confirmation']])}${submit('Send link')}</form></section>`;
 bind($('#login-form'),async d=>{result(await sb.auth.signInWithPassword(d));location.href=new URLSearchParams(location.search).get('next')==='admin'?'/admin.html':'/portal/index.html';});
 bind($('#signup-form'),async d=>{const data=result(await sb.auth.signUp({...d,options:{emailRedirectTo:location.origin+'/portal/index.html'}}));if(data.session)location.href='/portal/profile.html';else status('Check your email to confirm your account. Delivery depends on the configured email service.');});
 bind($('#recovery-form'),async d=>{if(d.kind==='reset')result(await sb.auth.resetPasswordForEmail(d.email,{redirectTo:location.origin+'/portal/set-password.html'}));else result(await sb.auth.resend({type:'signup',email:d.email,options:{emailRedirectTo:location.origin+'/portal/index.html'}}));status('If this address is eligible, a new link will arrive by email.');});
}
function password(){status('');$('#app-content').innerHTML=me?`<section class="app-card"><form class="app-form" id="password-form">${field('password','New password','password','','required minlength="12" autocomplete="new-password"')}${field('confirm','Repeat new password','password','','required minlength="12" autocomplete="new-password"')}${submit('Update password')}</form></section>`:'<section class="app-card"><p>This link has expired or could not be verified. Open the link in the browser where you requested it, or request another.</p><a href="/portal/login.html">Request a new link →</a></section>';if(me)bind($('#password-form'),async d=>{if(d.password!==d.confirm)throw new Error('The passwords must match.');result(await sb.auth.updateUser({password:d.password}));status('Password updated.');});}
async function profile(){const p=me.profile||{};$('#app-content').innerHTML=`<section class="app-card"><form class="app-form" id="profile-form">${field('full_name','Full name','text',p.full_name,'required maxlength="120" minlength="2"')}${field('phone','Phone','tel',p.phone,'maxlength="30"')}${field('school','School / institution','text',p.school,'maxlength="180"')}<p>${esc(me.user.email)}</p>${submit('Save profile')}</form></section>`;bind($('#profile-form'),async d=>{await api('profile',d);status('Your profile is saved.');});}
async function dashboard(){const data=await api('dashboard');$('#app-content').innerHTML=data.registrations.length?data.registrations.map(r=>`<article class="app-card"><span class="app-badge">${esc(r.edition_slug)}</span><span class="app-badge">${esc(r.status)}</span><h2>${esc(r.school)}</h2><p class="app-ref">Registration ${r.id}</p><p>${r.participant_count} participant(s) · ${money(r.amount_paise)} · ${esc(r.kind)}</p><p>Coordinator: ${esc(r.coordinator_name)} · ${esc(r.phone)}</p><div class="app-table-wrap"><table class="app-table"><thead><tr><th>Participant</th><th>Grade</th><th>Allocation</th><th>Attendance</th></tr></thead><tbody>${r.elan_attendees.map(a=>`<tr><td>${esc(a.full_name)}</td><td>${esc(a.grade)}</td><td>${esc(a.allocation||'To be assigned')}</td><td>${a.checked_in_at?'Checked in':'Not checked in'}</td></tr>`).join('')}</tbody></table></div><p>${r.amount_paise===0?'No payment required. Await organiser confirmation.':'Payment: '+esc(r.elan_payments[0]?.status||'not started')}</p>${r.status==='pending'&&r.amount_paise>0?`<button data-pay="${r.id}">Continue to secure checkout</button>`:''}${r.status==='confirmed'?'<p>Your place is confirmed. Show this registration reference at check-in.</p>':''}</article>`).join(''):'<section class="app-card"><h2>Your story starts here.</h2><p>You have no registrations yet. Check which editions are open, or complete your profile while you wait.</p><a class="app-button" href="/register.html">View registration</a></section>';
 for(const btn of document.querySelectorAll('[data-pay]'))btn.onclick=async()=>{btn.disabled=true;try{const order=await api('payment-order',{registration_id:btn.dataset.pay});if(!window.Razorpay)await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=res;s.onerror=()=>rej(new Error('Could not load secure checkout.'));document.head.append(s);});const checkout=new window.Razorpay({key:order.key,amount:order.amount,currency:'INR',order_id:order.order_id,name:'Élan Summit',prefill:{email:me.user.email},handler:async response=>{try{await api('payment-verify',{registration_id:btn.dataset.pay,payment_id:response.razorpay_payment_id,signature:response.razorpay_signature});status('Payment verified. Your registration is confirmed.');await dashboard();}catch(e){status(e.message+' Your payment may still be processing; contact support before retrying.',true);}}});checkout.open();}catch(e){status(e.message,true);}finally{btn.disabled=false;}};
 const announcements=result(await sb.from('elan_announcements').select('*').eq('published',true).order('created_at',{ascending:false}).limit(20));if(announcements.length)$('#app-content').insertAdjacentHTML('beforeend','<section class="app-card"><h2>Latest updates</h2>'+announcements.map(a=>`<article><span class="app-badge">${esc(a.edition_slug)}</span><h3>${esc(a.title)}</h3><p class="app-copy">${esc(a.body)}</p></article>`).join('')+'</section>');
}
async function register(){const editions=result(await sb.from('elan_editions').select('*,elan_registration_settings(*)').eq('published',true).eq('status','upcoming'));const open=editions.filter(e=>e.elan_registration_settings?.registration_open&&(!e.elan_registration_settings.registration_closes_at||new Date(e.elan_registration_settings.registration_closes_at)>new Date()));if(!open.length){$('#app-content').innerHTML='<section class="app-card"><h2>The next chapter is taking shape.</h2><p>Registration has not opened. Dates, prices and eligibility will appear here when confirmed.</p><a href="/schools.html#enquire">Start a school enquiry →</a></section>';return;}
 const p=me.profile||{};$('#app-content').innerHTML=`<section class="app-card"><form class="app-form" id="registration-form">${select('edition_slug','Edition',open.map(e=>[e.slug,e.title]))}${select('kind','Registration type',[['individual','Individual participant'],['school','School delegation']])}${field('school','School / institution','text',p.school,'required minlength="2" maxlength="180"')}${field('coordinator_name','Participant / coordinator name','text',p.full_name,'required minlength="2" maxlength="120"')}${field('phone','Contact phone','tel',p.phone,'required minlength="6" maxlength="30"')}<div id="attendee-fields"></div><button type="button" class="secondary" id="add-attendee">Add participant</button><div id="registration-terms"></div>${check('consent','I have read the participation terms, have permission to provide these details, and confirm that any required parent or guardian consent has been obtained.')}${submit('Submit registration')}</form></section>`;
 let count=0;const add=()=>{if(count>=50)return;const n=count++;$('#attendee-fields').insertAdjacentHTML('beforeend',`<fieldset data-attendee><legend>Participant ${n+1}</legend>${field('name_'+n,'Full name','text','','required minlength="2" maxlength="120"')}${field('age_'+n,'Age on event date','number','','required min="1" max="100"')}${field('grade_'+n,'Grade / year','text','','required maxlength="60"')}<button type="button" class="secondary" data-remove>Remove</button></fieldset>`);for(const b of document.querySelectorAll('[data-remove]'))b.onclick=()=>{if(document.querySelectorAll('[data-attendee]').length>1)b.closest('fieldset').remove();update();};update();};
 function update(){const f=$('#registration-form');const e=open.find(e=>e.slug===f.elements.edition_slug.value),s=e.elan_registration_settings,n=document.querySelectorAll('[data-attendee]').length;$('#registration-terms').innerHTML=`<p>${esc(e.venue||'')} · ${esc(e.starts_on||'')}<br>Eligible ages: ${s.min_age}–${s.max_age} · ${money(s.price_paise)} per participant<br><strong>Total: ${money(s.price_paise*n)}</strong></p><details><summary>Participation terms · ${esc(s.terms_version)}</summary><p class="app-copy">${esc(s.terms_text)}</p></details>`;$('#add-attendee').hidden=f.elements.kind.value==='individual';}
 $('#add-attendee').onclick=add;add();$('#registration-form').elements.edition_slug.onchange=update;$('#registration-form').elements.kind.onchange=()=>{if($('#registration-form').elements.kind.value==='individual')[...document.querySelectorAll('[data-attendee]')].slice(1).forEach(x=>x.remove());update();};let request_key=newId();
 bind($('#registration-form'),async(d,f)=>{const s=open.find(e=>e.slug===d.edition_slug).elan_registration_settings;const rows=[...f.querySelectorAll('[data-attendee]')].map(el=>{const inputs=el.querySelectorAll('input');return {full_name:inputs[0].value,age:Number(inputs[1].value),grade:inputs[2].value};});await api('register',{...d,request_key,terms_version:s.terms_version,consent:f.elements.consent.checked,attendees:rows});location.href='/portal/index.html';});
}
async function schedule(){const rows=result(await sb.from('elan_schedule').select('*').eq('published',true).order('starts_at'));$('#app-content').innerHTML=rows.length?rows.map(r=>`<article class="app-card"><span class="app-badge">${esc(r.edition_slug)}</span><h2>${esc(r.title)}</h2><p>${when(r.starts_at)}${r.ends_at?' – '+when(r.ends_at):''}</p><p>${esc(r.location)}</p><p class="app-copy">${esc(r.details)}</p></article>`).join(''):'<div class="app-card"><h2>The programme is being prepared.</h2><p>Confirmed sessions will appear here.</p><a href="/schedule.html">Browse the 2026 programme →</a></div>';}
async function support(){const data=await api('dashboard');$('#app-content').innerHTML=`<section class="app-card"><h2>Ask the team.</h2><form class="app-form" id="support-form">${field('subject','Subject','text','','required minlength="3" maxlength="160"')}${area('message','How can we help?')}${submit('Send request')}</form></section>`+data.support.map(t=>`<article class="app-card"><span class="app-badge">${esc(t.status)}</span><h3>${esc(t.subject)}</h3><p class="app-copy">${esc(t.message)}</p>${t.reply?`<h3>Team reply</h3><p class="app-copy">${esc(t.reply)}</p>`:'<p>The team has not replied yet.</p>'}</article>`).join('');bind($('#support-form'),async d=>{await api('support',d);await support();status('Your question has been saved. Check here for the reply.');});}
async function submissions(){const data=await api('dashboard');const registrations=data.registrations.filter(r=>r.status!=='cancelled');$('#app-content').innerHTML=(registrations.length?`<section class="app-card"><h2>Submit a report.</h2><form class="app-form" id="submission-form">${select('registration_id','Registration',registrations.map(r=>[r.id,r.school+' · '+r.edition_slug]))}${field('title','Report title','text','','required minlength="2" maxlength="160"')}${field('file','PDF · maximum 10 MB','file','','required accept="application/pdf"')}${submit('Upload report')}</form></section>`:'<p class="app-empty">Create a registration before submitting a report.</p>')+data.submissions.map(s=>`<article class="app-card"><h3>${esc(s.title)}</h3><p>${when(s.created_at)}</p><button data-download="${s.id}">Download PDF</button></article>`).join('');if($('#submission-form'))bind($('#submission-form'),async(d,f)=>{const file=f.elements.file.files[0];if(file.type!=='application/pdf'||file.size>10485760)throw new Error('Choose a PDF under 10 MB.');const u=await api('submission-upload',{registration_id:d.registration_id});result(await sb.storage.from('elan-submissions').uploadToSignedUrl(u.path,u.token,file,{contentType:'application/pdf'}));await api('submission-save',{registration_id:d.registration_id,title:d.title,path:u.path});await submissions();status('Report uploaded.');});bindDownloads();}
function bindDownloads(){for(const b of document.querySelectorAll('[data-download]'))b.onclick=async()=>{try{const u=await api('submission-download',{id:b.dataset.download});location.href=u.signedUrl;}catch(e){status(e.message,true);}};}
const contentFields={
 elan_editions:[['slug','Edition slug'],['title','Title'],['summary','Summary','textarea'],['starts_on','Start date','date'],['ends_on','End date','date'],['venue','Venue'],['status','Status',['archive','upcoming']],['published','Published','checkbox']],
 elan_registration_settings:[['edition_slug','Edition slug'],['registration_open','Registration open','checkbox'],['price_paise','Price per participant in paise (₹1 = 100 paise)','number'],['capacity','Capacity','number'],['min_age','Minimum age','number'],['max_age','Maximum age','number'],['registration_closes_at','Registration deadline','datetime-local'],['terms_version','Terms version'],['terms_text','Participation terms','textarea']],
 elan_guests:[['slug','Profile slug'],['edition_slug','Edition slug'],['name','Name'],['role','Event role'],['position','Professional title'],['bio','Biography','textarea'],['image_url','Portrait URL'],['sort_order','Display order','number'],['published','Published','checkbox']],
 elan_announcements:[['edition_slug','Edition slug'],['title','Title'],['body','Announcement','textarea'],['published','Published','checkbox']],
 elan_schedule:[['edition_slug','Edition slug'],['title','Session title'],['starts_at','Starts at','datetime-local'],['ends_at','Ends at','datetime-local'],['location','Location'],['details','Details','textarea'],['published','Published','checkbox']],
 elan_media:[['edition_slug','Edition slug'],['title','Title'],['alt_text','Image description'],['image_url','Image URL'],['category','Category',['Venue','Crisis Command','Cent$ible','Stage','People']],['credit','Photo credit'],['sort_order','Display order','number'],['published','Published','checkbox']]
};
async function admin(){if(me.role==='participant'){status('This account does not have organiser access.',true);$('#app-content').innerHTML='<p>Ask the director to grant access to your verified account.</p>';return;}
 const tabs=[['elan_registrations','Registrations'],['elan_enquiries','Enquiries'],['elan_support','Help desk'],['elan_submissions','Reports'],['elan_editions','Editions'],['elan_registration_settings','Registration settings'],['elan_guests','Guests'],['elan_media','Gallery'],['elan_announcements','Announcements'],['elan_schedule','Programme'],...(me.role==='admin'?[['elan_audit','Activity log']]:[])];
 $('#app-content').innerHTML=`<p>Signed in as ${esc(me.user.email)} · ${esc(me.role)}</p><div class="app-tabs">${tabs.map(([v,l])=>`<button data-table="${v}" class="secondary" aria-pressed="false">${l}</button>`).join('')}</div><div id="admin-content"></div><div id="admin-editor"></div>`;
 let table='elan_registrations',offset=0,current=[],loadVersion=0;
 async function load(){const version=++loadVersion;status('Loading…');const data=await api('admin-list',{table,offset});if(version!==loadVersion)return;current=data.rows;for(const b of document.querySelectorAll('[data-table]'))b.setAttribute('aria-pressed',String(b.dataset.table===table));$('#admin-editor').replaceChildren();
 $('#admin-content').innerHTML=`<div class="app-actions"><span>${data.total} records${data.total?' · showing '+(offset+1)+' to '+Math.min(offset+50,data.total):''}</span><button id="export-page" class="secondary" ${current.length?'':'disabled'}>Export this page (CSV)</button>${contentFields[table]&&me.role==='admin'?'<button id="new-record">Add new</button>':''}</div><div id="admin-rows">${current.map((r,i)=>renderRow(r,i)).join('')||'<p class="app-empty">No records yet.</p>'}</div><div class="app-actions"><button id="previous" ${offset===0?'disabled':''}>Previous</button><button id="next" ${offset+50>=data.total?'disabled':''}>Next</button></div>`;
 $('#previous').onclick=()=>{offset=Math.max(0,offset-50);run(load);};$('#next').onclick=()=>{offset+=50;run(load);};$('#export-page').onclick=()=>downloadCSV(current);if($('#new-record'))$('#new-record').onclick=()=>editor({edition_slug:'next',sort_order:0});
 for(const b of document.querySelectorAll('[data-edit]'))b.onclick=()=>editor(current[Number(b.dataset.edit)]);
 for(const b of document.querySelectorAll('[data-reg-status]'))b.onclick=()=>run(async()=>{await api('registration-status',{id:b.dataset.id,status:b.dataset.regStatus});await load();});
 for(const b of document.querySelectorAll('[data-checkin]'))b.onclick=()=>run(async()=>{await api('check-in',{id:b.dataset.checkin,checked:b.dataset.checked!=='true'});await load();});
 for(const f of document.querySelectorAll('[data-allocation]'))bind(f,async d=>{await api('allocation',{id:f.dataset.allocation,allocation:d.allocation});status('Allocation saved.');});
 for(const f of document.querySelectorAll('[data-reply]'))bind(f,async d=>{await api('support-reply',{id:f.dataset.reply,...d});await load();status('Reply saved.');});
 for(const f of document.querySelectorAll('[data-enquiry-status]'))bind(f,async d=>{await api('enquiry-status',{id:f.dataset.enquiryStatus,status:d.status});await load();status('Enquiry updated.');});
 bindDownloads();status('');}
 function renderRow(r,i){if(contentFields[table])return `<article class="app-card"><span class="app-badge">${esc(r.edition_slug||r.slug)}</span><h3>${esc(r.title||r.name||'Registration settings')}</h3><p>${'published' in r?(r.published?'Published':'Draft'):r.registration_open?'Registration open':'Registration closed'}</p>${me.role==='admin'?`<button data-edit="${i}">Edit</button>`:''}</article>`;
 if(table==='elan_registrations')return `<article class="app-card"><span class="app-badge">${esc(r.status)}</span><h3>${esc(r.school)}</h3><p class="app-ref">${r.id}</p><p>${esc(r.coordinator_name)} · ${esc(r.phone)} · ${money(r.amount_paise)}</p><p>Payment: ${esc(r.elan_payments[0]?.status||'none')}</p>${r.elan_attendees.map(a=>`<details><summary>${esc(a.full_name)} · ${esc(a.grade)} · age ${a.age}</summary><p>${esc(a.allocation||'Unassigned')}</p>${me.role==='admin'?`<form class="app-form" data-allocation="${a.id}">${field('allocation','Country / cabinet / role','text',a.allocation,'maxlength="300"')}${submit('Save allocation')}</form>`:''}<button data-checkin="${a.id}" data-checked="${!!a.checked_in_at}">${a.checked_in_at?'Undo check-in':'Check in'}</button></details>`).join('')}${me.role==='admin'&&r.status==='pending'?`<div class="app-actions">${r.amount_paise===0?`<button data-id="${r.id}" data-reg-status="confirmed">Confirm free registration</button>`:''}<button class="secondary" data-id="${r.id}" data-reg-status="cancelled">Cancel registration</button></div>`:''}</article>`;
 if(table==='elan_enquiries')return `<article class="app-card"><span class="app-badge">${esc(r.kind)}</span><h3>${esc(r.full_name)}</h3><p>${esc(r.email)}</p><details><summary>Enquiry details</summary>${Object.entries(r.details).map(([k,v])=>`<p><strong>${esc(k)}</strong><br>${esc(v)}</p>`).join('')}</details><form class="app-form" data-enquiry-status="${r.id}">${select('status','Status',[['new','New'],['in_progress','In progress'],['resolved','Resolved']],r.status)}${submit('Update status')}</form></article>`;
 if(table==='elan_support')return `<article class="app-card"><h3>${esc(r.subject)}</h3><p class="app-copy">${esc(r.message)}</p><form class="app-form" data-reply="${r.id}">${area('reply','Reply',r.reply)}${select('status','Status',[['answered','Answered'],['closed','Closed']],r.status)}${submit('Save reply')}</form></article>`;
 if(table==='elan_submissions')return `<article class="app-card"><h3>${esc(r.title)}</h3><p class="app-ref">Registration ${r.registration_id}</p><p>${when(r.created_at)}</p><button data-download="${r.id}">Download PDF</button></article>`;
 return `<article class="app-card"><p>${esc(r.action)} · ${when(r.created_at)}</p><p class="app-ref">${esc(r.actor_id)} / ${esc(r.target)}</p></article>`;
 }
 function editor(record){const fields=contentFields[table];$('#admin-editor').innerHTML=`<section class="app-card app-editor"><h2>${record.id||record.slug?'Edit record':'New record'}</h2><form class="app-form" id="content-form">${fields.map(([name,label,type])=>{let val=record[name]??'';if(type==='checkbox')return check(name,label,val);if(type==='textarea')return area(name,label,val);if(Array.isArray(type))return select(name,label,type.map(v=>[v,v]),val);if(type==='datetime-local'&&val){const d=new Date(val);val=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}return field(name,label,type||'text',val);}).join('')}${['elan_media','elan_guests'].includes(table)?field('image_file','Upload a JPEG, PNG or WebP · up to 8 MB','file','','accept="image/jpeg,image/png,image/webp"'):''}<p class="form-note">Dates and times use your browser’s local timezone. Uncheck Published to hide content. Opening registration requires dates, a venue, a deadline and participation terms.</p>${submit('Save record')}</form></section>`;$('#admin-editor').scrollIntoView({block:'start'});$('#content-form input')?.focus({preventScroll:true});
 bind($('#content-form'),async(d,f)=>{const row={...record};for(const [name,label,type] of fields){row[name]=type==='checkbox'?f.elements[name].checked:type==='number'?Number(d[name]):type==='datetime-local'&&d[name]?new Date(d[name]).toISOString():d[name];}const file=f.elements.image_file?.files[0];if(file){if(file.size>8388608)throw new Error('Use an image smaller than 8 MB.');const u=await api('media-upload',{mime:file.type});result(await sb.storage.from('elan-public-media').uploadToSignedUrl(u.path,u.token,file,{contentType:file.type}));row.image_url=u.url;}await api('admin-save',{table,record:row});await load();status('Record saved.');});}
 for(const b of document.querySelectorAll('[data-table]'))b.onclick=()=>{table=b.dataset.table;offset=0;run(load);};await load();
}
async function run(fn){try{await fn();}catch(e){status(e.message,true);}}

async function guide(){ $('#app-content').innerHTML='<section class="app-card"><h2>Prepare for the next edition.</h2><p>Check your registration for confirmation and allocations. The organiser will publish arrival information, session times and preparation instructions in the programme and announcements.</p><div class="app-actions"><a class="app-button" href="/portal/schedule.html">Programme</a><a class="app-button" href="/portal/help-desk.html">Ask the team</a></div><p><a href="/flagship.html">Explore the Crisis Command format →</a></p><p>The 2026 format is historical; next-edition instructions will be confirmed separately.</p></section>'; }

const shell=$('[data-app]');let me;
if(shell){try{const {data:{session}}=await sb.auth.getSession();if(session){$('#sign-out').hidden=false;$('#sign-out').onclick=async()=>{result(await sb.auth.signOut());location.href='/portal/login.html';};me=await api('me');if(me.role!=='participant')$('#admin-link').hidden=false;}
 const mode=shell.dataset.app;
 if(mode==='login')login();else if(mode==='password')password();else if(!me&&mode==='admin'){adminLogin();}else if(!me){$('#app-content').innerHTML='<section class="app-card"><h2>Sign in to continue.</h2><p>Your registration and participant details are only visible to your account and authorised organisers.</p><a class="app-button" href="/portal/login.html">Sign in or create an account</a></section>';status('');}else{status('');await ({dashboard,profile,register,schedule,submissions,support,admin,guide}[mode]||dashboard)();}
}catch(e){status(e.message,true);}}
